import Foundation

// The assistant without the model: safety rules, calculators, synonyms, guide search and the message
// the model receives. This is the Swift version of eval/pipeline.py.
//
// To avoid hand-copying what may change, the rules, synonyms, system message and constants
// are read from Contenido/datos/reglas.json, generated by app/exportar_datos.py from eval/pipeline.py.
// The only logic written here is the calculators', and it is checked against Python with casos.json
// (app/check or the app's «Autocomprobación» button).
//
// Does not import llama, so it can be compiled and tested with swiftc on the Mac, without Xcode or a simulator.
//
// The JSON keys stay in Spanish: app/exportar_datos.py writes them, hence the CodingKeys below.

struct Rule: Codable {
    let pattern: String
    let text: String

    enum CodingKeys: String, CodingKey {
        case pattern = "patron", text = "texto"
    }
}

struct Synonym: Codable {
    let pattern: String
    let extra: String

    enum CodingKeys: String, CodingKey {
        case pattern = "patron", extra
    }
}

struct Constants: Codable {
    let powerBankEfficiency: Double
    let powerBankEfficiencyText: String
    let water: Double
    let waterText: String
    let fridgeHours: Int
    let fullFreezerHours: Int
    let halfFreezerHours: Int

    enum CodingKeys: String, CodingKey {
        case powerBankEfficiency = "eficiencia_pb", powerBankEfficiencyText = "eficiencia_pb_txt"
        case water = "agua", waterText = "agua_txt"
        case fridgeHours = "nevera_h", fullFreezerHours = "congelador_lleno_h", halfFreezerHours = "congelador_medio_h"
    }
}

struct RulesData: Codable {
    let systemPrompt: String
    let rules: [Rule]
    let synonyms: [Synonym]
    let spanishSources: [String]
    let topK: Int
    let maxPerSource: Int
    let queryPrefix: String
    let numberPattern: String
    let numberWords: [String: Double]
    let constants: Constants

    enum CodingKeys: String, CodingKey {
        case systemPrompt = "system_rag", rules = "reglas", synonyms = "sinonimos", spanishSources = "espana"
        case topK = "top_k", maxPerSource = "max_por_fuente", queryPrefix = "prefijo_consulta"
        case numberPattern = "num", numberWords = "palabras_numero", constants = "constantes"
    }
}

struct Chunk: Codable {
    let source: String
    let url: String
    let text: String
    let vec: [Float]

    enum CodingKeys: String, CodingKey {
        case source = "fuente", url, text = "texto", vec
    }
}

struct PreparedPrompt {
    let user: String      // full message the model receives (rules + calculations + guides + question)
    let rules: [String]
    let calculations: [String]
    let chunks: [Chunk]
}

final class Pipeline {
    let data: RulesData
    let index: [Chunk]
    private var cache: [String: NSRegularExpression] = [:]

    init(folder: URL) throws {
        data = try JSONDecoder().decode(RulesData.self, from: Data(contentsOf: folder.appendingPathComponent("reglas.json")))
        index = try JSONDecoder().decode([Chunk].self, from: Data(contentsOf: folder.appendingPathComponent("index.json")))
    }

    // MARK: - Regular expressions (equivalent to Python's re.search)

    private func regex(_ pattern: String, caseInsensitive: Bool = false) -> NSRegularExpression {
        let key = (caseInsensitive ? "i:" : "") + pattern
        if let r = cache[key] { return r }
        let r = try! NSRegularExpression(pattern: pattern, options: caseInsensitive ? [.caseInsensitive] : [])
        cache[key] = r
        return r
    }

    /// First match: [group 0, group 1, …] or nil.
    func search(_ pattern: String, _ text: String, caseInsensitive: Bool = false) -> [String]? {
        let range = NSRange(text.startIndex..., in: text)
        guard let m = regex(pattern, caseInsensitive: caseInsensitive).firstMatch(in: text, range: range) else { return nil }
        return (0..<m.numberOfRanges).map { i in
            let r = m.range(at: i)
            guard r.location != NSNotFound, let rr = Range(r, in: text) else { return "" }
            return String(text[rr])
        }
    }

    /// Group 1 of every match (like re.findall with one group).
    func allMatches(_ pattern: String, _ text: String) -> [String] {
        let range = NSRange(text.startIndex..., in: text)
        return regex(pattern).matches(in: text, range: range).compactMap { m in
            guard let rr = Range(m.range(at: 1), in: text) else { return nil }
            return String(text[rr])
        }
    }

    // MARK: - 1. Safety rules

    func ruleIndices(_ q: String) -> [Int] {
        let ql = q.lowercased()
        return data.rules.indices.filter { search(data.rules[$0].pattern, ql) != nil }
    }

    // MARK: - 2. Deterministic calculators

    func number(_ s: String) -> Double {
        let t = s.trimmingCharacters(in: .whitespaces).lowercased()
        if let w = data.numberWords[t] { return w }
        var u = t
        if search(#"^\d{1,3}(\.\d{3})+$"#, u) != nil { u = u.replacingOccurrences(of: ".", with: "") }
        return Double(u.replacingOccurrences(of: ",", with: ".")) ?? 0
    }

    func format(_ x: Double) -> String {
        String(format: "%.1f", x).replacingOccurrences(of: ".", with: ",").replacingOccurrences(of: ",0", with: "")
    }

    func calculators(_ q: String) -> [String] {
        let ql = q.lowercased()
        let NUM = data.numberPattern
        let c = data.constants
        var out: [String] = []

        // Power bank → phone charges
        let mah = allMatches(#"(\d{1,3}(?:\.\d{3})+|\d+)\s*mah"#, ql)
        if (ql.contains("power bank") || ql.contains("powerbank") || ql.contains("batería externa")) && mah.count >= 2 {
            let values = mah.map(number)
            let powerBank = values.max()!, phone = values.min()!
            var bankCount = 1.0
            if let k = search(NUM + #"\s+power ?banks?"#, ql), !["un", "una", "uno"].contains(k[1]) { bankCount = number(k[1]) }
            let total = powerBank * bankCount
            let charges = total * c.powerBankEfficiency / phone
            out.append("Cargas completas aproximadas = \(Int(total)) mAh × \(c.powerBankEfficiencyText) ÷ \(Int(phone)) mAh = \(format(charges)) cargas (una power bank entrega ~70 % de su capacidad nominal).")
        }

        // Fridge / freezer hours
        let h = search(NUM + #"\s*horas"#, ql)
        let isPerishable = search("nevera|frigor|leche|pollo|carne|pescado|huevo|sobras|yogur", ql) != nil
        let freezer = ql.contains("congelador") || (ql.contains("congel") && search("nevera|frigor", ql) == nil)
        if let h = h, isPerishable || freezer {
            let hours = number(h[1])
            let limit: Int
            let name: String
            if freezer {
                let isHalfFull = ql.contains("medio")
                limit = isHalfFull ? c.halfFreezerHours : c.fullFreezerHours
                name = isHalfFull ? "congelador medio lleno" : "congelador lleno"
            } else {
                limit = c.fridgeHours
                name = "nevera"
            }
            let remaining = Double(limit) - hours
            if remaining > 0 {
                out.append("Margen restante = \(limit) h (\(name) sin abrir) − \(format(hours)) h = \(format(remaining)) h.")
            } else {
                let action = name == "nevera"
                    ? " Tira los perecederos (leche, carne, pescado, huevos, sobras) aunque huelan o parezcan bien."
                    : " Lo que se haya descongelado del todo no se vuelve a congelar."
                out.append("Han pasado \(format(hours)) h y el límite (\(name) sin abrir) es de \(limit) h: el límite ya se ha superado.\(action)")
            }
        }

        // Water: amount needed or days it lasts
        let people = search(#"somos\s+"# + NUM, ql) ?? search(NUM + #"\s+personas"#, ql) ?? search(#"somos\s+"# + NUM + #"\s+en casa"#, ql)
        if ql.contains("agua") || ql.contains("litros") {
            let p: Double? = people.map { number($0[1]) }
            let liters = search(NUM + #"\s*litros"#, ql)
            let days = search(#"para\s+"# + NUM + #"\s*d[ií]as"#, ql)
            if let p = p, p != 0, let liters = liters, ql.contains("cuántos días") || ql.contains("llega") {
                let L = number(liters[1])
                let d = L / (p * c.water)
                out.append("Días de agua = \(format(L)) L ÷ (\(format(p)) personas × \(c.waterText) L/día) = \(format(d)) días.")
            } else if let p = p, p != 0, let days = days {
                let d = number(days[1])
                let L = p * d * c.water
                out.append("Agua necesaria = \(format(p)) personas × \(format(d)) días × \(c.waterText) L = \(format(L)) litros como mínimo.")
            }
        }
        return out
    }

    // MARK: - 3. Guide search

    /// Adds the wording of the US guides to the question (for search only).
    func expand(_ q: String) -> String {
        let extra = data.synonyms.filter { search($0.pattern, q, caseInsensitive: true) != nil }.map { $0.extra }
        return extra.isEmpty ? q : q + " (" + extra.joined(separator: ", ") + ")"
    }

    /// Text turned into a vector for search (with EmbeddingGemma's query prefix).
    func queryText(_ q: String) -> String { data.queryPrefix + expand(q) }

    func isSpanish(_ t: Chunk) -> Bool { data.spanishSources.contains { t.source.contains($0) } }

    /// The 6 closest chunks, at most 2 per guide, Spanish guides first. Returns positions in the index.
    func retrieve(_ query: [Float]) -> [Int] {
        let scores: [Double] = index.map { t in
            var s = 0.0
            for i in 0..<min(query.count, t.vec.count) { s += Double(query[i]) * Double(t.vec[i]) }
            return s
        }
        let order = scores.indices.sorted { scores[$0] > scores[$1] }
        var top: [Int] = []
        var perSource: [String: Int] = [:]
        for i in order {
            let f = index[i].source
            if perSource[f, default: 0] < data.maxPerSource {
                top.append(i)
                perSource[f, default: 0] += 1
            }
            if top.count == data.topK { break }
        }
        return top.filter { isSpanish(index[$0]) } + top.filter { !isSpanish(index[$0]) }
    }

    // MARK: - 4. Putting it together

    func prepare(_ q: String, chunks positions: [Int]) -> PreparedPrompt {
        let rules = ruleIndices(q).map { data.rules[$0].text }
        let calculations = calculators(q)
        let docs = positions.map { index[$0] }
        var parts: [String] = []
        if !rules.isEmpty { parts.append("REGLAS DE SEGURIDAD:\n" + rules.map { "- " + $0 }.joined(separator: "\n")) }
        if !calculations.isEmpty { parts.append("DATOS CALCULADOS:\n" + calculations.map { "- " + $0 }.joined(separator: "\n")) }
        let guides = docs.enumerated().map { e in
            "[\(e.offset + 1)] (\(e.element.source)\(isSpanish(e.element) ? " · España" : "")) \(e.element.text)"
        }
        parts.append("GUÍAS:\n" + guides.joined(separator: "\n\n"))
        parts.append("PREGUNTA: \(q)")
        return PreparedPrompt(user: parts.joined(separator: "\n\n"), rules: rules, calculations: calculations, chunks: docs)
    }

    /// Removes the line-break hyphens the model copies from PDFs («in-\nmediato») and the line breaks.
    func clean(_ answer: String) -> String {
        var t = answer
        if let r = try? NSRegularExpression(pattern: #"(\w)-\s*\n\s*(\w)"#) {
            t = r.stringByReplacingMatches(in: t, range: NSRange(t.startIndex..., in: t), withTemplate: "$1$2")
        }
        if let r = try? NSRegularExpression(pattern: #"\s*\n\s*"#) {
            t = r.stringByReplacingMatches(in: t, range: NSRange(t.startIndex..., in: t), withTemplate: " ")
        }
        return t.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    // MARK: - 5. Safety net for figures

    /// Numbers in a text, normalized to a decimal comma («1.8» → «1,8»; «una» → «1»).
    func numbersIn(_ text: String) -> Set<String> {
        var out = Set<String>()
        let t = text.lowercased()
        let r = regex(#"\d+(?:[.,]\d+)?"#)
        for m in r.matches(in: t, range: NSRange(t.startIndex..., in: t)) {
            guard let rr = Range(m.range, in: t) else { continue }
            var n = String(t[rr]).replacingOccurrences(of: ".", with: ",")
            if n.hasSuffix(",0") { n = String(n.dropLast(2)) }
            out.insert(n)
        }
        let words = regex(#"\b(un|una|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\b"#)
        for m in words.matches(in: t, range: NSRange(t.startIndex..., in: t)) {
            guard let rr = Range(m.range, in: t), let v = data.numberWords[String(t[rr])] else { continue }
            out.insert(format(v))
        }
        return out
    }

    /// If there is a calculated figure and the model's answer omits it (or gives another), returns the lines
    /// the app must show with the correct figure. Exact values are guaranteed by code, not the model.
    func missingFigures(answer: String, calculations: [String]) -> [String] {
        let inAnswer = numbersIn(answer)
        let rl = answer.lowercased()
        var missing: [String] = []
        for c in calculations {
            if c.hasPrefix("Han pasado") {
                // limit exceeded: the answer must say so, or say to throw it away
                let denies = rl.contains("no se ha superado") || rl.contains("no ha superado") || rl.contains("no se han superado")
                let warns = rl.contains("superad") || rl.contains("tira") || rl.contains("desech") || rl.contains("no la consumas")
                    || rl.contains("no lo consumas") || rl.contains("no los consumas") || rl.contains("no las consumas")
                if denies || !warns {   // e.g. «Sí, la leche huele bien y no se ha superado el límite» (real evaluation failure)
                    missing.append(c)
                }
                continue
            }
            // result = last number before the unit («= 1 h.», «= 1,8 cargas», «= 18 litros», «= 1,3 días»)
            let r = regex(#"=\s*(\d+(?:,\d+)?)\s*(h\b|cargas|días|litros)"#)
            let ms = r.matches(in: c, range: NSRange(c.startIndex..., in: c))
            guard let m = ms.last, let rr = Range(m.range(at: 1), in: c) else { continue }
            if !inAnswer.contains(String(c[rr])) { missing.append(c) }
        }
        return missing
    }
}

// MARK: - Verification against Python (casos.json)

struct TestCase: Codable {
    let q: String
    let rules: [Int]
    let calculations: [String]
    let expanded: String
    let top: [Int]?

    enum CodingKeys: String, CodingKey {
        case q, rules = "reglas", calculations = "calculos", expanded = "expandida", top
    }
}

enum Verification {
    /// Rules, calculators and synonyms: must match eval/pipeline.py exactly.
    static func pureLogic(_ p: Pipeline, _ cases: [TestCase]) -> (failures: Int, text: String) {
        var failures = 0
        var details: [String] = []
        for c in cases {
            var errors: [String] = []
            let r = p.ruleIndices(c.q)
            if r != c.rules { errors.append("reglas \(r) ≠ \(c.rules)") }
            let k = p.calculators(c.q)
            if k != c.calculations { errors.append("cálculo «\(k.joined(separator: " | "))» ≠ «\(c.calculations.joined(separator: " | "))»") }
            let e = p.expand(c.q)
            if e != c.expanded { errors.append("sinónimos «\(e)» ≠ «\(c.expanded)»") }
            if !errors.isEmpty {
                failures += 1
                details.append("✗ \(c.q)\n   " + errors.joined(separator: "\n   "))
            }
        }
        let header = "Reglas, calculadoras y sinónimos: \(cases.count - failures) de \(cases.count) iguales que en Python."
        return (failures, ([header] + details).joined(separator: "\n"))
    }

    /// Fixed safety-net cases: (question, model answer, should it add the figure?).
    static func safetyNet(_ p: Pipeline) -> (failures: Int, text: String) {
        let fridge = "Se ha ido la luz hace 3 horas, ¿la comida de la nevera sigue siendo segura?"
        let water = "Somos 4 en casa, ¿cuánta agua necesitamos para 3 días?"
        let milk = "La leche huele bien después de 5 horas sin luz. ¿Me la puedo beber?"
        let powerBank = "Tengo una power bank de 10.000 mAh y mi móvil tiene 4000 mAh, ¿cuántas cargas me da?"
        let tests: [(String, String, Bool)] = [
            (fridge, "Sí, con 4 horas de margen restante la comida sigue siendo segura.", true),   // real simulator failure
            (fridge, "Sí, con 1 hora de margen restante la comida de la nevera sigue siendo segura.", false),
            (fridge, "Te queda una hora de margen si no abres la nevera.", false),
            (water, "Con 4 personas necesitas 18 litros de agua como mínimo para 3 días.", false),
            (water, "Necesitáis unos 12 litros.", true),
            (milk, "No la consumas aunque huela bien: el límite ya se ha superado.", false),
            (milk, "Sí, la leche huele bien y se puede beber.", true),
            (milk, "Sí, la leche huele bien y no se ha superado los 4 h de límite.", true),   // real failure (GS005)
            (powerBank, "Te da unas 1,8 cargas completas.", false),
            (powerBank, "Unas 2,5 cargas.", true),
        ]
        var failures = 0
        var details: [String] = []
        for (q, r, expected) in tests {
            let adds = !p.missingFigures(answer: r, calculations: p.calculators(q)).isEmpty
            if adds != expected { failures += 1; details.append("✗ «\(r)»: \(adds ? "añade" : "no añade") el dato") }
        }
        let header = "Red de seguridad de las cifras: \(tests.count - failures) de \(tests.count) casos bien."
        return (failures, ([header] + details).joined(separator: "\n"))
    }
}
